import {DATA} from './data.js';
import {resolveParts,sizes,torqueRow,torqueValue,SOURCE,HP_SOURCE,SF_SOURCE,GF_SOURCE} from './logic.js';
const $=id=>document.getElementById(id);
let pn=10, currentText='';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>url?`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`:`<span>${label} · Original-PDF finns i projektunderlaget. Publik dokumentlänk återstår.</span>`;
function option(value,label){return `<option value="${esc(value)}">${esc(label)}</option>`;}
function diagram(dn,blind){return `<div class="diagram"><svg viewBox="0 0 520 170" role="img" aria-label="Principskiss av flänsförband. Inte en måttritning."><defs><pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#53716a" stroke-width=".5" opacity=".22"/></pattern></defs><rect width="520" height="170" fill="url(#grid)"/><g stroke="#a7c58b" stroke-width="1.5"><path d="M35 62H167V108H35" fill="#284b45"/><path d="M35 72H155V98H35" fill="#123337"/><path d="M167 44H183V126H167Z" fill="#637c61"/><path d="M184 37H198V133H184Z" fill="#244741"/><path d="M204 49H211V121H204Z" fill="#cde99d"/>${blind?'<path d="M216 37H238V133H216Z" fill="#49716c"/><path d="M239 73H278V97H239" fill="#30534e"/><path d="M249 74V96M255 74V96M261 74V96M267 74V96" stroke-width=".6"/>':'<path d="M217 37H231V133H217Z" fill="#244741"/><path d="M232 44H248V126H232Z" fill="#637c61"/><path d="M248 62H378V108H248Z" fill="#284b45"/><path d="M260 72H378V98H260" fill="#123337"/>'}<path d="M174 48H244M174 122H244" stroke="#e1e8d7" stroke-width="5"/><path d="M176 40V55M241 40V55M176 115V130M241 115V130" stroke="#d4dfc7" stroke-width="6"/><path d="M20 85H400" stroke="#87a58c" stroke-dasharray="5 5" stroke-width=".7"/><path d="M403 38H417M403 132H417M410 38V132" stroke-width=".8"/></g><g fill="#a8c1ae" font-family="monospace" font-size="10"><text x="50" y="143">PE-RÖR</text><text x="280" y="37">${blind?'BLINDFLÄNS + UTTAG':'FLÄNSFÖRBAND'}</text><text x="424" y="89">DN ${dn??'—'}</text><text x="20" y="20" font-size="8" fill="#749387">PRINCIPSKISS · EJ SKALENLIG</text></g></svg></div>`;}
function state(){return {family:$('family').value,od:+$('od').value,sdr:+$('sdr').value,pn,connection:$('connection').value,collar:$('collar').value};}
function fillSizes(){const old=+$('od').value;const opts=sizes($('family').value);$('od').innerHTML=opts.map(d=>option(d,`Ø ${d} mm`)).join('');$('od').value=opts.includes(old)?old:opts.includes(200)?200:opts[0];$('collar-field').hidden=$('family').value!=='standard';}
function row(name,detail,qty,wait=false){return `<div class="pick-row"><div><strong>${name}</strong><small>${detail}</small></div><span class="qty ${wait?'wait':''}">${qty}</span></div>`;}
function renderParts(){
 const s=state(),r=resolveParts(s),blind=s.connection==='blind';
 const title=`PE Ø${s.od} · SDR${s.sdr} · PN${s.pn}`;
 if(r.blocked){$('parts-result').innerHTML=`<div class="result-top"><span class="caption">Ditt förband</span><span class="status warn">UNDERLAG SAKNAS</span></div>${diagram(r.dn,blind)}<div class="empty"><h3>${r.message}</h3><p>${r.detail??'Välj en annan kombination eller kontrollera produktens datablad.'}</p></div><div class="source-link">${link(r.gf?GF_SOURCE:SOURCE,r.gf?'Öppna GF:s verktyg':'Visa IBECO-katalogen')}</div>`;$('picklist').innerHTML=row('Ingen färdig plocklista',esc(r.message),'Kontroll krävs',true);currentText=`VABON FLÄNSGUIDEN – PROTOTYP\n${title}\n${r.message}\n${r.detail??''}\nIngen verifierad plocklista.\nKälla: ${r.gf?GF_SOURCE:SOURCE}`;return;}
 const f=r.flange,c=r.selectedCollar;
 const notices=[...r.issues,'Bultlängd och åtdragningsmoment är inte fastställda för detta förband.'];
 const family=s.family==='ibeco_sf'?'IBECO reducerad SF-fläns':'IBECO bordring + PP-stållösfläns';
 $('parts-result').innerHTML=`<div class="result-top"><div class="section-head"><span class="step">2</span><h2>Ditt förband</h2></div><span class="status">KATALOGUPPGIFT</span></div>${diagram(r.dn,blind)}<div class="big-result"><div><div class="caption">Flänsanslutning</div><div class="dn">DN ${r.dn}</div><div class="result-sub">${title}</div></div><span class="pn-tag">PN ${s.pn}</span></div><div class="stats"><div class="stat"><span class="caption">Bultar · flänsens hålbild</span><b>${f.bolts} × M${f.thread}</b><small>Bultlängd återstår att kontrollera</small></div><div class="stat"><span class="caption">Åtdragningsmoment</span><b class="missing">Ej fastställt</b><small>Kräver exakt produkt och packning</small></div></div><div class="notice">${notices.map(esc).join('<br>')}</div><div class="source-link">${link(SOURCE,`IBECO 2023 · s. ${s.family==='ibeco_sf'?'202':'200–201, 225'}${blind?', 222':''}`)}<br>Produktuppgifter behöver slutkontrolleras mot aktuellt datablad.</div>`;
 let rows=[];
 if(s.family==='standard'){
  rows.push(row(`${s.collar==='long'?'Lång':'Kort'} PE-bordring Ø${s.od} · SDR${s.sdr}`,c?`RSK ${c.rsk} · L ${c.length} mm · L1 ${c.l1} mm · H ${c.h} mm`:'Saknas i inläst katalogunderlag',c?(s.connection==='pair'?'2 st':'1 st'):'Kontroll krävs',!c));
  rows.push(row(`PP-stållösfläns DN${r.dn} · PN${s.pn}`,`IBECO ${f.article} · RSK ${f.rsk}`,s.connection==='pair'?'2 st':'1 st'));
 }else rows.push(row(`Reducerad SF-fläns Ø${s.od} → DN${r.dn} · PN${s.pn}`,`SDR${s.sdr} · Artikel och komplett förband kontrolleras mot sidan 202`,'Kontroll krävs',true));
 if(blind)rows.push(row(`Blindfläns DN${r.dn} med gängat uttag`,r.blind?`Katalog: ${r.blind.article} · G50 / 2″ · borrning PN${r.blind.pn}`:'PN-variant, uttag och artikel behöver verifieras hos IBECO',r.blind?'1 st':'Kontroll krävs',!r.blind));
 if(s.connection==='fixed')rows.push(row(`Fast metallfläns / ventil DN${r.dn}`,`Kontrollera PN${s.pn}, hålbild och tätningsyta`,'Ej identifierad',true));
 rows.push(row('Packning',`Välj typ och material för exakt förband · moment beror på packningen`,'Ej vald',true));
 rows.push(row(`${f.bolts} bultar M${f.thread} + muttrar och brickor`,'Bultlängd, kvalitet och smörjning behöver fastställas. Hålbild från vald fläns.','Längd saknas',true));
 $('picklist').innerHTML=rows.join('');
 currentText=`VABON FLÄNSGUIDEN – PROTOTYP 0.1\n${title}\n${family}\nAnslutning: ${$('connection').selectedOptions[0].textContent}\nDN ${r.dn}; flänsens hålbild ${f.bolts} x M${f.thread}\n${c?`Bordring RSK ${c.rsk}, ${s.connection==='pair'?2:1} st`:'Bordring / SF-artikel behöver kontrolleras'}\n${f.article?`Lösfläns ${f.article}, RSK ${f.rsk}, ${s.connection==='pair'?2:1} st\n`:''}${blind?`Blindfläns: ${r.blind?r.blind.article+' (kataloguppgift)':'artikel behöver verifieras'}\n`:''}Packning: ej vald\nBultlängd: ej fastställd\nÅtdragningsmoment: ej fastställt\n${r.issues.join('\n')}\nKälla: IBECO produktkatalog 2023, s. ${s.family==='ibeco_sf'?'202':'200–201, 225'}${blind?', 222':''}\n${SOURCE}\nKontrollera aktuell produktdata före beställning och montering.`;
}
function fillTorque(){const family=$('tfamily').value,p=+$('tpn').value,old=+$('tsize').value;const rows=DATA.torques.filter(x=>x.family===family&&x.pn===p);$('tsize').innerHTML=rows.map(x=>option(x.od,`Ø ${x.od} / DN ${x.dn}`)).join('');$('tsize').value=rows.some(x=>x.od===old)?old:rows.some(x=>x.od===200)?200:rows[0].od;const pair=$('tpair').value;$('tpair').innerHTML=family==='hp'?option('a','Stål–HP · EPDM-profilpackning')+option('b','HP–HP · EPDM-profilpackning'):option('a','Stål–VP/SF · O-ring')+option('b','Stål–VP/SF · EPDM-profilpackning');if(pair)$('tpair').value=pair;renderTorque();}
function renderTorque(){const family=$('tfamily').value,p=+$('tpn').value,r=torqueRow(family,p,+$('tsize').value),v=torqueValue(r,$('tpair').value);if(!r||!v){$('torque-result').textContent='Underlag saknas för valt förband.';return;}$('torque-result').innerHTML=`<div class="result-top"><span class="caption">Reinert-Ritz · ${family==='hp'?'HP':'Reducerad VP/SF'}</span><span class="status">TABELLVÄRDE</span></div><h2 style="margin-top:25px">Ø ${r.od} / DN ${r.dn} · PN${p}</h2><p class="result-sub">${esc($('tpair').selectedOptions[0].textContent)}</p><div class="torque-number">${v[1]} <small>Nm</small></div><span class="caption">Rekommenderat moment enligt tabellen</span><div class="range"><div><span class="caption">Min enligt tabell</span><b>${v[0]} Nm</b></div><div><span class="caption">Max enligt tabell</span><b>${v[2]} Nm</b></div></div><h3>Förutsättningar i källan</h3><ul class="conditions"><li>20 °C, horisontell montering utan böjbelastning.</li><li>Exakt flänspar och packning enligt tillverkarens anvisning.</li><li>Nya, förzinkade och smorda bultar/muttrar, kvalitet 5.6 eller högre.</li><li>Brickor under bult och mutter. Korsvis åtdragning i flera steg.</li><li>För profilpackning: stålförstärkt EPDM från Kroll & Ziller eller Klinger enligt källan.</li></ul><div class="notice">Min/max är gränser i källtabellen, inte instruktioner för momentsteg. Tillverkaren anger vägledande värden och garanterar inte långtidstäthet. Fullständig monteringsanvisning behöver följas.</div><div class="source-link">${link(family==='hp'?HP_SOURCE:SF_SOURCE,`Visa original · sida ${r.page}`)}<br>Gäller inte automatiskt GF- eller IBECO-produkter.</div>`;}
const sources=[['IBECO · produktkatalog 2023','Bordringar s. 200–202. Blindflänsar s. 222. Lösflänsar s. 225. Bultsatser s. 232–235. Moment och automatisk bultlängd för IBECO ingår ännu inte.',SOURCE],['Reinert-Ritz · HP PN10 / PN16','Min, rekommenderat och max moment för stål–HP och HP–HP med profilpackning. Källans monteringsvillkor visas tillsammans med värdet.',HP_SOURCE],['Reinert-Ritz · reducerad VP/SF PN10 / PN16','Moment för stål–VP/SF med O-ring eller profilpackning. Ingen automatisk överföring till andra fabrikat.',SF_SOURCE],['GF · flänskopplingsverktyg','Referenskontroll för ELGEF Plus, SDR11, PE200/DN200, PP-stål och EPDM-profilpackning. Verktyget visar 8 × M20, 85 mm och 45 Nm i testfallet. PN och komplett produktvillkor måste dokumenteras innan det används som apprekommendation.',GF_SOURCE],['IBECO · blindfläns med gängat uttag','Utpekad som vanlig produkt hos er i PN10 och PN16. PN16-artiklar för större DN är ännu inte verifierade i prototypen.','https://ibeco.se/produkter/blindflans-gangat-uttag']];
$('source-list').innerHTML=sources.map(([title,desc,url])=>`<div class="source-item"><h3>${title}</h3><p>${desc}</p>${link(url,'Öppna källan')}</div>`).join('');
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b));});document.querySelectorAll('.panel').forEach(x=>x.hidden=x.id!==b.dataset.tab);}));
document.querySelectorAll('#pn button').forEach(b=>b.addEventListener('click',()=>{pn=+b.dataset.value;document.querySelectorAll('#pn button').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});renderParts();}));
$('family').addEventListener('change',()=>{fillSizes();renderParts();});['od','sdr','connection','collar'].forEach(id=>$(id).addEventListener('change',renderParts));
['tfamily','tpn'].forEach(id=>$(id).addEventListener('change',fillTorque));['tsize','tpair'].forEach(id=>$(id).addEventListener('change',renderTorque));
$('reset').addEventListener('click',()=>{$('family').value='standard';$('sdr').value='11';$('connection').value='blind';$('collar').value='long';fillSizes();$('od').value='200';document.querySelector('#pn [data-value="10"]').click();});
$('copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(currentText);$('toast').textContent='Plocklistan är kopierad';}catch{$('toast').textContent='Urklipp stöds inte. Använd Skriv ut / PDF.';}$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),3000);});
$('print').addEventListener('click',()=>window.print());fillSizes();renderParts();fillTorque();
